# agent/tools.py\nimport requests\nimport time\n\ndef search_hotels_tool(query, location, max_attempts=3, backoff_factor=1):\n    """Search for hotels with retry/backoff to handle transient failures.\n\n    Args:\n        query (str): Search query.\n        location (str): Location for the search.\n        max_attempts (int): Maximum number of retry attempts.\n        backoff_factor (int): Base factor for exponential backoff.\n\n    Returns:\n        dict: JSON response from the hotel search API.\n    """\n    attempt = 0\n    while attempt < max_attempts:\n        try:\n            url = f"https://api.hotel.com/search?q={query}&loc={location}"\n            response = requests.get(url)\n            response.raise_for_status()\n            return response.json()\n        except requests.exceptions.RequestException as e:\n            attempt += 1\n            if attempt >= max_attempts:\n                raise\n            # Exponential backoff: 1, 2, 4 seconds, etc.\n            sleep_time = backoff_factor * (2 ** (attempt - 1))\n            time.sleep(sleep_time)\n